export type Account = { id: string; login: string; name: string | null; avatar_url: string; html_url: string; scopes: string[] | null; method: AuthMethod; added_at: string }
export type ActionsProgress = { done: number; total: number }
export type Actor = { login: string }
export type AddResult = { workspace: Workspace; steps: string[]; warning: AppError | null }
export type AddWorkspace = { path: string; name: string; push_repo: string | null; create: NewRepo | null; reference_repo: string | null; ignore: string[] }
export type Alert = { kind: AlertKind; number: number; state: string; severity: Severity; key: string; title: string; description: string | null; package: string | null; ecosystem: string | null; location: string | null; vulnerable_range: string | null; patched: string | null; ghsa: string | null; cve: string | null; cvss: number | null; tool: string | null; validity: string | null; push_protection_bypassed: boolean; reason: string | null; comment: string | null; html_url: string; created_at: string; updated_at: string | null; closed_at: string | null }
export type AlertKind = "dependency" | "code" | "secret"
export type AppError = { code: string; detail: string | null; status: number | null }
